const rawContent = $input.first().json.message?.content || $input.first().json.text || '[]';
const cleaned = rawContent.replace(/```json\n?|```/g, '').trim();
let parsed = [];

try {
  const data = JSON.parse(cleaned);
  parsed = Array.isArray(data) ? data : (data.sites || data.urls || [data]);
} catch (e) {
  parsed = [{
    site_name: 'Parse Error Fallback',
    url: 'https://example.com',
    reason: rawContent
  }];
}

const webhookData = $('1. Webhook (국가/제품 입력)').first().json;
const body = webhookData.body || webhookData;

return parsed.map((site, idx) => ({
  json: {
    index: idx + 1,
    country: body.country || 'US',
    product: body.product || 'Unknown Product',
    site_name: site.site_name || site.name || `Site ${idx + 1}`,
    url: site.url,
    category: site.category || 'Review/Community',
    proxy_type: body.proxy_type || 'datacenter',
    extraction_type: body.extraction_type || 'markdown'
  }
}));

// Basic LLM Chain(Gemini) 출력값 파싱
const rawContent = $input.first().json.text || $input.first().json.output || '[]';
const cleaned = rawContent.replace(/```json\n?|```/g, '').trim();
let parsed = [];

try {
  const data = JSON.parse(cleaned);
  parsed = Array.isArray(data) ? data : (data.sites || data.urls || [data]);
} catch (e) {
  parsed = [{
    site_name: 'JSON Parse Error',
    url: 'https://example.com',
    category: 'Error',
    reason: rawContent
  }];
}

const inputParams = $('2. 수집할 국가/제품 설정 (수정 가능)').first().json;

return parsed.map((site, idx) => ({
  json: {
    index: idx + 1,
    country: inputParams.country || 'US',
    product: inputParams.product || 'Unknown Product',
    site_name: site.site_name || site.name || `Site ${idx + 1}`,
    category: site.category || 'Review / Community',
    url: site.url || '',
    reason: site.reason || site.description || ''
  }
}));
